-- Item 5: DEFIS do ano-calendário 2026 pelo art. 144-F (incl. Res. CGSN 196/2026 art. 1º). Mesma vigência e valor da sn7.
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('sn8-obr-defis-simples', 'OBRIGACAO_REGIME', 'DEFIS', 'SIMPLES', NULL, NULL, '{"statusBase":"OBRIGATORIA","condicoes":[],"inativa":{"status":"OBRIGATORIA","fonte":"Res. CGSN 140/2018 art. 72 caput (sem exceção para a inativa)"}}', 'Res. CGSN 140/2018 art. 72 caput e § 1º (anual, até 31/03 do ano seguinte) até o ano-calendário 2025; ano-calendário 2026: art. 144-F (incl. Res. CGSN 196/2026 art. 1º, vigência em 24/11/2026), Defis até 31/03/2027 no módulo do aplicativo PGDAS-D 2018. O art. 72 é revogado em 01/01/2027 (Res. CGSN 190/2026 art. 8º XXI; efeitos pelo art. 9º) e as informações do ano-calendário seguinte passam ao PGDAS-D (Res. CGSN 140/2018 art. 38-B, incl. Res. CGSN 190/2026)', 'https://normasinternet2.receita.fazenda.gov.br/api/consulta-externa/ato/154694/visao/multivigente', 'af0387ef601c947b71bbbea50f319c5a20d59f0cfd93cb9e6e3c7bd24449e52a', '2018-01-01', '2027-03-31', 'PUBLISHED', 'sn7-obr-defis-simples', 'BE-INCR-SIMPLES-CGSN-196 item 5 (dono, chat, 2026-11-26: "Ratifico F-196-1 a 4 como recomendado, executa"): o art. 144-F (incl. Res. CGSN 196/2026) responde por lei à ambiguidade A1 da sn7 (Defis × PGDAS-D do ano-calendário 2026). Mesma vigência e valor; só a fonte muda', 'migracao:BE-INCR-SIMPLES-CGSN-196', 'migracao:BE-INCR-SIMPLES-CGSN-196', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
